TWComponent.script:
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

var ind = 0;

if(!!tw.local.transactionIDs){

	tw.local.sqlStatement[ind] = new tw.object.SQLStatement();
	tw.local.sqlStatement[ind].sql = "DELETE FROM "+tw.env.LKP_DB_Schema+".ODC_SELECTEDTRANSACTIONS WHERE REQUESTID = ?";
	tw.local.sqlStatement[ind].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.requestID));
	ind++;
	for(var i =0; i<tw.local.transactionIDs.listLength; i++){
	
		tw.local.sqlStatement[ind] = new tw.object.SQLStatement();
		tw.local.sqlStatement[ind].sql = "DELETE FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE ID = ?";
		tw.local.sqlStatement[ind].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.transactionIDs[i]));
		ind++;
		
	}
	

}

function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

var ind = 0;

for (var i = 0; i < tw.local.transactionIDs.listLength; i++) {
    tw.local.sqlStatement[ind] = new tw.object.SQLStatement();
    tw.local.sqlStatement[ind].parameters = new tw.object.listOf.SQLParameter();
    tw.local.sqlStatement[ind].sql = "INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS ( " + 
                        "REQUESTID, TRANSACTIONID, AMOUNTLINKEDINBPM, AMOUNTINCURRENTREQ, ISDELETED) " +    
                        "VALUES (?, ?, ?, ?, ?)";
    
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.requestID));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.transactionIDs[i]));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.data[i].existAmount));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.data[i].amountAllocatedForCurrencyRequest));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter("No"));

    ind++;
}

function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

var ind = 0;


for (var i = 0; i < tw.local.data.listLength; i++) {
    
    var sqlStatement = new tw.object.SQLStatement();
    sqlStatement.sql = "SELECT ID FROM FINAL TABLE (INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION ( " + 
                            "ACCOUNTNO, REFERENCENO, POSTINGDATE, VALUEDATE, TRANSACTIONAMOUNT, AMOUNTLINKEDINBPM, AMOUNTFORCURRENTREQ, AMOUNTINREQCURRENCY) " +    
                            "VALUES (?, ?, ?, ?, ?, ?, ?, ?));";

    sqlStatement.parameters = new tw.object.listOf.SQLParameter();
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].accountNo));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].referenceNumber));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].postingDate));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].valueDate));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].transactionAmount));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].existAmount));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].amountAllocatedForCurrencyRequest));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].allocatedAmountInRequestCurrency));

    tw.local.sqlStatement[ind] = new tw.object.SQLStatement();
    tw.local.sqlStatement[ind] = sqlStatement;
    ind++;
}


