    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.transactionIDs[i]));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.data[i].existAmount));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter(tw.local.data[i].amountAllocatedForCurrencyRequest));
    tw.local.sqlStatement[ind].parameters.insertIntoList(tw.local.sqlStatement[ind].parameters.listLength, addSQLParameter("No"));

    ind++;
}

function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

