    sqlStatement.sql = "SELECT ID FROM FINAL TABLE (INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION ( " + 
                            "ACCOUNTNO, REFERENCENO, POSTINGDATE, VALUEDATE, TRANSACTIONAMOUNT, AMOUNTLINKEDINBPM, AMOUNTFORCURRENTREQ, AMOUNTINREQCURRENCY) " +    
                            "VALUES (?, ?, ?, ?, ?, ?, ?, ?));";

    sqlStatement.parameters = new tw.object.listOf.SQLParameter();
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].accountNo));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].referenceNumber));
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, addSQLParameter(tw.local.data[i].postingDate));
